<?= $this->section('styles') ?><link rel="stylesheet" href="<?= base_url('css/admin-notifications.css?v=1') ?>"><?= $this->endSection() ?>
<?= $this->section('content') ?>
<header class="admin-notifications-header"><div><h1>Notifications</h1><p><?php if($unreadCount===0): ?>No unread notifications.<?php elseif($unreadCount===1): ?>1 unread notification.<?php else: ?><?= (int)$unreadCount ?> unread notifications.<?php endif ?></p></div><form method="post" action="<?= site_url('notifications/read-all') ?>"><?= csrf_field() ?><button class="secondary mark-all" type="submit" <?= (!$notificationWritesEnabled || $unreadCount===0)?'disabled':'' ?>><span class="material-symbols-outlined" aria-hidden="true">done_all</span>Mark all as read</button></form></header>
<?php if(!$notificationWritesEnabled): ?><p class="alert" role="status">Notification changes are disabled pending database approval. This page is read-only.</p><?php endif ?>
<nav class="notification-filters" aria-label="Filter notifications"><?php foreach(['all'=>'All notifications','unread'=>'Unread','read'=>'Read'] as $key=>$label): ?><a href="<?= site_url('notifications?filter='.$key) ?>" <?= $filter===$key?'aria-current="page"':'' ?>><?= esc($label) ?><?= $key==='unread'?' ('.(int)$unreadCount.')':'' ?></a><?php endforeach ?></nav>
<?php if(!$notifications): ?><div class="admin-notification-empty"><span class="material-symbols-outlined" aria-hidden="true">notifications_off</span><p><?= $filter==='unread'?'No unread notifications.':($filter==='read'?'No read notifications.':'No notifications yet.') ?></p></div><?php else: ?><div class="admin-notification-list"><?php foreach($notifications as $notification): $read=(bool)$notification['is_read']; $type=(string)($notification['notification_type']??''); $icon=str_starts_with($type,'payment_')?'payments':($type==='reservation_cancelled'?'event_busy':($type==='reservation_submitted'?'event_note':'notifications')); $rawDate=$notification['created_at']??null; $date=$rawDate?(new DateTimeImmutable($rawDate,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone(config('Booking')->timezone)):null; ?><article class="admin-notification <?= $read?'is-read':'is-unread' ?>"><span class="notification-icon material-symbols-outlined" aria-hidden="true"><?= esc($icon) ?></span><div class="notification-content"><div class="notification-title"><h2><?= esc($notification['title']) ?></h2><span class="notification-read-state"><?= $read?'Read':'Unread' ?></span></div><p><?= esc($notification['message']) ?></p><?php if($date): ?><time datetime="<?= esc($date->format(DateTimeInterface::ATOM),'attr') ?>" title="<?= esc($rawDate,'attr') ?> UTC"><?= esc($date->format('M j, Y · g:i A')) ?> Manila</time><?php else: ?><span class="notification-read-state">Date unavailable</span><?php endif ?><div class="notification-row-actions"><?php if(!empty($notification['existing_reservation_id'])): ?><a href="<?= site_url('admin/reservations/'.(int)$notification['existing_reservation_id']) ?>"><span class="material-symbols-outlined" aria-hidden="true">event_note</span>View reservation</a><?php endif ?><?php if(!$read && $notificationWritesEnabled): ?><form method="post" action="<?= site_url('notifications/'.(int)$notification['id'].'/read') ?>"><?= csrf_field() ?><button type="submit"><span class="material-symbols-outlined" aria-hidden="true">done</span>Mark as read</button></form><?php endif ?></div></div><?php if(!$read): ?><span class="unread-dot" aria-hidden="true"></span><?php endif ?></article><?php endforeach ?></div><?= $pager ?><?php endif ?>
<?= $this->endSection() ?>
